INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (110501, 10021, 0.0, 1, "2019/07/31 12:00:00", "2030/12/17 14:59:59", "あうぅ～残念さ～\nマジムンに魂を\n奪われちゃったかな～？", 4, 24, 24015, "カオリ（サマー）", 0.0, 4, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (110501, 10021, 0.0, 2, "2019/07/31 12:00:00", "2030/12/17 14:59:59", "今日は踊りのキレも悪いよ～\nゴーヤーっぽいもの食べて、元気回復さ～！", 4, 24, 24016, "カオリ（サマー）", 4.0, 1, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (110501, 10021, 0.0, 3, "2019/07/31 12:00:00", "2030/12/17 14:59:59", "マジムンだらけで目が回るさ～！\nふらふらさ～！", 4, 24, 24017, "カオリ（サマー）", 0.0, 4, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (110501, 10021, 0.0, 4, "2019/07/31 12:00:00", "2030/12/17 14:59:59", "なんくるない、なんくるない\n次、頑張ればいいんだよ～！\n海で泳いで\nリフレッシュするさー！", 1, 24, 24018, "カオリ（サマー）", 5.2, 2, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (110501, 10021, 0.0, 5, "2019/07/31 12:00:00", "2030/12/17 14:59:59", "恥ずかしいところ\n見られちゃったね～\n水着？　水着のことじゃないよー？", 5, 24, 24019, "カオリ（サマー）", 4.2, 6, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (110501, 10021, 0.0, 6, "2019/07/31 12:00:00", "2030/12/17 14:59:59", "絶好調さ～！　この調子で\n海の平和を取り戻すよ～！\n楽しい夏が待ってるさ～！", 2, 24, 24020, "カオリ（サマー）", 0.0, 2, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (110501, 10021, 0.0, 7, "2019/07/31 12:00:00", "2030/12/17 14:59:59", "何匹で襲ってきたって\n私はマブイを落っことさないよ～！\nくしゅん！　あ……\n今のくしゃみで落っこちたかも～？", 1, 24, 24021, "カオリ（サマー）", 6.4, 6, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (110501, 10021, 0.0, 8, "2019/07/31 12:00:00", "2030/12/17 14:59:59", "ひーやーさーさー♪\n戦いの後は、踊りを踊って\n気分スッキリさ～！", 2, 24, 24022, "カオリ（サマー）", 0.0, 2, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (110501, 10021, 0.0, 9, "2019/07/31 12:00:00", "2030/12/17 14:59:59", "あれ～？　戦ってるうちに\n水着がどっか行っちゃった～？\nねぇキミ、どっかで見なかった～？\nなんで離れるさ～？", 6, 24, 24023, "カオリ（サマー）", 10.08, 3, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (110501, 10021, 0.0, 10, "2019/07/31 12:00:00", "2030/12/17 14:59:59", "まだまだ私は元気だよ～！\nマジムンでもなんでも、\nどんとこーいさー♪", 1, 24, 24024, "カオリ（サマー）", 5.0, 2, 0.0);
INSERT INTO `v1_acf81dbe558f652a2dfc6fe4764cbdcdb20b714ef50a0db2a9ce4ca9056814d5` VALUES (110501, 10021, 0.0, 11, "2019/07/31 12:00:00", "2030/12/17 14:59:59", "私の空手は世界最強さ～！\n夏の陽射しと青い海も合わされば、\n向かうところ敵なしだよー！", 2, 24, 24025, "カオリ（サマー）", 0.0, 2, 0.0);
